def _validate_layer_temperature_interval(
    layer: InsulationLayer,
    *,
    index: int,
    t_hot: float,
    t_cold: float,
) -> None:
    args = [layer]# type: ignore
    kwargs = {'index': index, 't_hot': t_hot, 't_cold': t_cold}# type: ignore
    return _mutmut_trampoline(x__validate_layer_temperature_interval__mutmut_orig, x__validate_layer_temperature_interval__mutmut_mutants, args, kwargs, None)


def x__validate_layer_temperature_interval__mutmut_orig(
    layer: InsulationLayer,
    *,
    index: int,
    t_hot: float,
    t_cold: float,
) -> None:
    min_temp, max_temp = _layer_temperature_range(layer)
    layer_hot_side = max(t_hot, t_cold)
    if min_temp <= layer_hot_side <= max_temp:
        return
    raise ValueError(
        f"Температура горячей стороны слоя изоляции #{index + 1} "
        f"({_fmt_temp(layer_hot_side)} °C) вне диапазона "
        f"материала '{layer.material}': {_fmt_temp(min_temp)}…{_fmt_temp(max_temp)} °C"
    )


