    r_ext = 1.0 / alpha

    # --- 7. Коэффициент запаса ---
    merged = merge_coefficients(coefficients)
    k = params.safety_factor or merged.get("safety_factor", 1.1)
    location_factor = merged.get(location_key(params.location), 1.0)

